 this.pointers.set(id,p);if(platform){this.selectedPlatform=platform;const held=[...this.pointers.values()].filter(p=>p.platform===platform);if(held.length===2){const[a,b]=held;const base=Math.atan2(b.point.y-a.point.y,b.point.x-a.point.x);for(const h of held){h.baseAngle=base;h.bodyAngle=platform.angle;}}this.feedback='Platform grabbed. Add a second finger to rotate it.';}
