export function compareGravity(a,b,mode='race'){if(mode==='survival')return a.clock-b.clock||a.lives-b.lives||a.orbCount-b.orbCount;if(a.complete!==b.complete)return a.complete?1:-1;if(mode==='orbs'&&a.orbCount!==b.orbCount)return a.orbCount-b.orbCount;if(a.complete&&b.complete&&a.finishedAt!==b.finishedAt)return b.finishedAt-a.finishedAt;return a.orbCount-b.orbCount||b.changes-a.changes||b.mistakes-a.mistakes;}
